    public AuditController(Audit audit) {
        this.audit = audit;
    }

    /** The sheet's audit lines newest first, only those about the named person when a name is given. */
    @GetMapping
    public List<String> lines(@PathVariable @NotBlank @Size(max = 100) String sheetId,
