            String line = theirs.get(i);
            if (line.startsWith(left) && (line.endsWith(to) || line.contains(to + " "))) {
                from = i;
                break;
            }
        }
        List<String> all = new ArrayList<>(lines);
        all.addAll(theirs.subList(from, theirs.size()));
        return all;
    }''')
